import {drawWrapped} from './text-layout.js';
const cache=new Map();
export function loadImage(src){if(!cache.has(src))cache.set(src,new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;}));return cache.get(src);}
const lines=drawWrapped;
function contain(ctx,img,x,y,w,h){const scale=Math.min(w/img.width,h/img.height),dw=img.width*scale,dh=img.height*scale;ctx.drawImage(img,x+(w-dw)/2,y+(h-dh)/2,dw,dh);}
export function createPaper(mount,data){const canvas=document.createElement('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Prévia legível do seu presente');canvas.className='paper-surface';mount.append(canvas);const ctx=canvas.getContext('2d');let state=data,opened=false,zoom=1,version=0;
 function fit(){if(mount.clientWidth<25||mount.clientHeight<25)return;const fit=Math.min((mount.clientWidth-24)/canvas.width,(mount.clientHeight-24)/canvas.height)*zoom;canvas.style.width=Math.max(1,Math.round(canvas.width*fit))+'px';canvas.style.height=Math.max(1,Math.round(canvas.height*fit))+'px';mount.dataset.zoom=String(zoom);}
 async function paint(){const v=++version,s={...state};const [sprite,pattern,material,photo]=await Promise.all([loadImage('assets/'+s.theme.sheet+'.webp'),loadImage('assets/pattern-'+(s.pattern||'aniversario-0')+'.webp').catch(()=>null),loadImage('assets/material-'+(s.texture||'algodao')+'.webp').catch(()=>null),s.photo?loadImage(s.photo).catch(()=>null):null]);if(v!==version)return;
 const spread=s.format==='livro'&&opened,card=s.format==='cartao';canvas.width=spread?1400:card?1000:760;canvas.height=spread?940:card?720:1000;const w=canvas.width,h=canvas.height;
 ctx.fillStyle=s.color;ctx.fillRect(0,0,w,h);if(pattern){ctx.drawImage(pattern,0,0,w,h);}if(material){ctx.save();ctx.globalAlpha=.2;ctx.globalCompositeOperation='multiply';ctx.drawImage(material,0,0,w,h);ctx.restore();}
 ctx.fillStyle='#fffaf2';ctx.beginPath();ctx.roundRect(34,34,w-68,h-68,5);ctx.fill();if(material){ctx.save();ctx.globalAlpha=.12;ctx.drawImage(material,34,34,w-68,h-68);ctx.restore();}
 const cell=sprite.width/4,sx=(s.theme.col||0)*cell,sy=s.theme.row*cell;const character=(x,y,size)=>ctx.drawImage(sprite,sx,sy,cell,cell,x,y,size,size);
 ctx.fillStyle='#4b2c28';ctx.textAlign='center';const title=s.recipient?(s.format==='convite'?s.recipient:'Para '+s.recipient):'Alguém especial';
 if(spread){ctx.fillStyle='#e9ddd0';ctx.fillRect(w/2-2,34,4,h-68);ctx.fillStyle='#4b2c28';ctx.font='52px "Fraunces",Georgia';ctx.fillText('Nossa história.',350,130);ctx.fillStyle='#fffefa';ctx.save();ctx.translate(350,470);ctx.rotate(-.045);ctx.fillRect(-244,-247,488,510);if(photo)contain(ctx,photo,-224,-227,448,420);else character(-210,-220,420);ctx.fillStyle='#71584d';ctx.font='italic 28px "Fraunces",Georgia';ctx.fillText('Uma lembrança só nossa.',0,228);ctx.restore();ctx.fillStyle='#4b2c28';ctx.font='46px "Fraunces",Georgia';lines(ctx,title,1050,160,550,54,2);character(945,290,210);ctx.font='38px "Fraunces",Georgia';lines(ctx,s.message||'Que bom ter você na minha história.',1050,570,530,51,5);}
 else if(card){ctx.textAlign='left';ctx.font='24px "DM Sans",sans-serif';ctx.fillText(s.theme.label.toUpperCase(),75,98);if(photo&&opened)contain(ctx,photo,60,176,340,340);else character(60,176,340);ctx.font='48px "Fraunces",Georgia';lines(ctx,title,465,193,450,57,2);ctx.font='34px "Fraunces",Georgia';lines(ctx,opened?(s.message||'Que bom ter você na minha história.'):'Um pequeno gesto. Um carinho inteiro.',465,355,440,47,6);}
 else {const invite=s.format==='convite';ctx.font='24px "DM Sans",sans-serif';ctx.fillText(invite?'VOCÊ FAZ PARTE DESTE DIA':'UM MIMO. MIL SENTIMENTOS.',w/2,112);ctx.font='54px "Fraunces",Georgia';lines(ctx,title,w/2,205,w-145,63,2);if(photo&&opened){contain(ctx,photo,145,invite?302:305,w-290,invite?250:320);}else character(invite&&opened?225:170,invite&&opened?290:310,invite&&opened?310:420);ctx.font=(opened?'32':'31')+'px "Fraunces",Georgia';lines(ctx,opened?(s.message||'Que bom ter você na minha história.'):'Preparado com carinho, para você guardar.',w/2,opened?(invite?654:735):790,w-145,40,6);}
 if(s.format==='convite'&&opened){let date='';if(s.eventDate&&/^\d{4}-\d{2}-\d{2}$/.test(s.eventDate)){const [y,m,d]=s.eventDate.split('-');date=d+'/'+m+'/'+y;}ctx.font='24px "DM Sans",sans-serif';ctx.fillStyle='#4b2c28';ctx.textAlign='center';if(date)ctx.fillText(date,w/2,h-100);if(s.eventPlace)lines(ctx,s.eventPlace,w/2,h-65,w-130,30,2);}
 canvas.dataset.format=s.format;canvas.dataset.pattern=s.pattern||'';canvas.dataset.material=s.texture||'';canvas.dataset.character=s.theme.sheet;fit();}
 const observer=new ResizeObserver(fit);observer.observe(mount);paint();document.fonts.ready.then(paint);return {set(next){state=next;paint();},open(value){opened=value;paint();},zoom(value){zoom=Math.max(1,Math.min(2.2,value));fit();return zoom;},getZoom:()=>zoom,snapshot:()=>({format:state.format,opened,zoom,width:canvas.width,height:canvas.height,pattern:state.pattern,material:state.texture,version}),destroy(){observer.disconnect();canvas.remove();}};
}
